import{n as e}from"./createLucideIcon-DLmAVpDi.js";import{Ut as t,u as n}from"./index-CCOe1rrM.js";import{t as r}from"./PdfPageWorkspace-BC4xbP_V.js";var i=e(),a=n(`rearrange-pdf`),o={intro:`Rearrange Pages lets you reorder the pages of a PDF using simple move-up and move-down arrow buttons on each page thumbnail, then export the result as a new document — no drag-and-drop needed, and everything runs locally in your browser.`,whyItMatters:`Scanned or exported documents don’t always come out in the right order — a duplex scanner can interleave pages unexpectedly, or a document assembled from several sources can end up out of sequence. Fixing the order without specialized desktop software makes a document usable before you submit or share it.`,howItWorks:[`Select a PDF file — every page renders as a thumbnail in a grid so you can see the current order at a glance.`,`Use the up/down arrow buttons in the corner of each thumbnail to move that page earlier or later in the sequence, one position at a time.`,`The first page’s "move earlier" button and the last page’s "move later" button are disabled, since there’s nowhere further to move.`,`Click "Save new order" to generate the reordered document, then download it.`],examples:[{title:`Reordering scanned pages`,body:`Fix a scan where pages came out of sequence — for example page 3 scanned before page 2 — before submitting the file.`},{title:`Moving a cover page to the front`,body:`A merged document has its cover page buried in the middle — move it to the very front using the up-arrow button repeatedly.`}],mistakes:[`Forgetting to double check the final order before exporting — review the full thumbnail sequence, not just the pages you moved, since moving one page shifts every page around it.`,`Trying to move a page past the first or last position — the boundary arrow buttons are intentionally disabled rather than wrapping around.`],tips:[`Combine with Rotate PDF first if some pages also need orientation fixed — rearrange after rotation is applied, since each tool exports a separate result.`,`For a large page count, moving a page a long distance means clicking the arrow repeatedly — plan the target position before starting rather than moving one page at a time between many others.`],faqs:[{question:`Can I remove a page while reordering?`,answer:`This tool is for reordering only — use Delete Pages separately to remove pages, since the arrow controls here only move pages, they don’t have a remove option.`},{question:`Does the original file get changed?`,answer:`No — reordering exports a new PDF; your original upload stays untouched and is never modified in place.`},{question:`Can I reorder a very large PDF?`,answer:`Yes, though documents with many pages take a little longer to process since everything runs in your browser rather than on a server, and each thumbnail has to be rendered individually.`},{question:`Is there a drag-and-drop option?`,answer:`No — pages are reordered using the up/down arrow buttons on each thumbnail rather than dragging, which keeps the reordering precise on both desktop and touch devices.`}],related:[{label:`Rotate PDF`,href:`/document-tools/rotate-pdf`},{label:`Delete Pages`,href:`/document-tools/delete-pdf-pages`}]};function s(){return(0,i.jsx)(r,{mode:`rearrange`,toolName:a.name,tagline:a.tagline,description:a.description,path:`/document-tools/rearrange-pdf`,icon:t,breadcrumb:{label:`Rearrange Pages`},toolSlug:a.slug,article:o})}export{s as default};